1	#!/usr/bin/env node
2	/**
3	 * sc4sap Profile CLI — backend for the sap-option skill's multi-profile flows.
4	 *
5	 * All side effects (profile file writes, keychain updates, active-profile
6	 * pointer changes) live here so the skill markdown can stay declarative.
7	 *
8	 * Contracts:
9	 *   - JSON in / JSON out on stdin and stdout. Errors go to stderr and exit != 0.
10	 *   - Passwords are never accepted on the command line. Preferred: stdin
11	 *     payload field `passwordPrompt: true` — the CLI opens a masked dialog
12	 *     window (scripts/lib/password-prompt.mjs) so the secret never enters the
13	 *     chat. Legacy: stdin payload field `password`.
14	 *   - Exit codes: 0 ok, 1 usage, 2 validation, 3 not-found, 4 conflict,
15	 *     5 keychain, 9 unknown.
16	 *
17	 * Commands (subcommand is the first arg):
18	 *   list              — list all profiles with active marker
19	 *   show <alias>      — dump one profile (password never included)
20	 *   switch <alias>    — write active-profile.txt in cwd
21	 *   add               — read JSON from stdin: {alias, tier, host, client,
22	 *                       username, password, description?, language?,
23	 *                       systemType?, version?, abapRelease?, industry?,
24	 *                       activeModules?, copyFrom?, passwordPrompt?}
25	 *                       → create profile dir
26	 *   set-password <alias> — open the masked dialog, store the new password in
27	 *                       the OS keychain, point SAP_PASSWORD at it
28	 *   set-blocklist <strict|standard|minimal|custom> [<alias>]
29	 *                     — set `blocklistProfile` (L3 PreToolUse hook) in the
30	 *                       active (or given) profile's config.json
31	 *   remove <alias>    — archive to .trash (user must confirm alias in skill)
32	 *   purge [--all]     — permanently delete .trash entries > 7 days old
33	 *   migrate           — read JSON from stdin: {alias, tier} → convert
34	 *                       <cwd>/.sc4sap/sap.env into
35	 *                       $SC4SAP_HOME_DIR/profiles/<alias>/ and archive source
36	 *   detect-legacy     — print JSON with legacy detection state (for
37	 *                       SessionStart banner)
38	 *   keychain-set      — read JSON from stdin: {service, account, password}
39	 *   keychain-delete   — read JSON from stdin: {service, account}
40	 *   validate [<alias>] — run sanity checks against one or all profiles.
41	 *                        Output: {errors: [...], warnings: [...]}.
42	 *   version           — print CLI version + plugin-declared feature version
43	 */
44	
45	import {
46	  cpSync,
47	  existsSync,
48	  mkdirSync,
49	  readFileSync,
50	  readdirSync,
51	  renameSync,
52	  rmSync,
53	  statSync,
54	  writeFileSync,
55	} from 'node:fs';
56	import { createRequire } from 'node:module';
57	import { homedir } from 'node:os';
58	import { basename, dirname, join, resolve } from 'node:path';
59	import { fileURLToPath } from 'node:url';
60	import { promptPassword } from './lib/password-prompt.mjs';
61	
62	// Polyfill `require` for ESM so CJS modules load without breaking pure-ESM
63	// execution paths. Used by non-keyring imports; keyring uses a dedicated
64	// require anchored at runtime-deps/keyring/ — see loadKeyring below.
65	globalThis.require ||= createRequire(import.meta.url);
66	
67	// @napi-rs/keyring lives in runtime-deps/keyring/ (committed to the repo so
68	// git-clone installs work without npm install). Anchor createRequire there so
69	// Node resolves `@napi-rs/keyring` from runtime-deps/keyring/node_modules/
70	// rather than the plugin-root node_modules/ (which is empty for end users).
71	const KEYRING_REQUIRE = createRequire(
72	  join(dirname(fileURLToPath(import.meta.url)), '..', 'runtime-deps', 'keyring', 'package.json'),
73	);
74	
75	const KEYCHAIN_SERVICE_DEFAULT = 'sc4sap';
76	
77	const CLI_VERSION = '1.0.0';
78	// Multi-profile infrastructure was introduced here. Used by detect-legacy
79	// banner so the plugin can tell users what changed.
80	const MULTI_PROFILE_SINCE = '0.6.0';
81	
82	function sc4sapHome() {
83	  return process.env.SC4SAP_HOME_DIR || join(homedir(), '.sc4sap');
84	}
85	function profilesDir() {
86	  return join(sc4sapHome(), 'profiles');
87	}
88	function trashDir() {
89	  return join(profilesDir(), '.trash');
90	}
91	function legacyFiles(cwd) {
92	  return {
93	    env: join(cwd, '.sc4sap', 'sap.env'),
94	    config: join(cwd, '.sc4sap', 'config.json'),
95	    pointer: join(cwd, '.sc4sap', 'active-profile.txt'),
96	  };
97	}
98	
99	function die(code, message) {
100	  process.stderr.write(`${message}\n`);
101	  process.exit(code);
102	}
103	function jsonOut(obj) {
104	  process.stdout.write(`${JSON.stringify(obj, null, 2)}\n`);
105	}
106	
107	function parseDotenv(text) {
108	  const out = {};
109	  for (const raw of text.split(/\r?\n/)) {
110	    const line = raw.trim();
111	    if (!line || line.startsWith('#')) continue;
112	    const eq = line.indexOf('=');
113	    if (eq <= 0) continue;
114	    const k = line.slice(0, eq).trim();
115	    let v = line.slice(eq + 1).trim();
116	    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
117	      v = v.slice(1, -1);
118	    }
119	    out[k] = v;
120	  }
121	  return out;
122	}
123	function formatDotenv(record) {
124	  const lines = [];
125	  for (const [k, v] of Object.entries(record)) {
126	    if (v == null) continue;
127	    lines.push(`${k}=${v}`);
128	  }
129	  return `${lines.join('\n')}\n`;
130	}
131	
132	function normalizeTier(v) {
133	  const s = String(v || '').trim().toUpperCase();
134	  if (s === 'DEV' || s === 'QA' || s === 'PRD') return s;
135	  return null;
136	}
137	
138	// SAP_SYSTEM_TYPE is the MCP server's deployment axis: `onprem` | `cloud` (`legacy` kept for old
139	// profiles). The server reads any other value as `cloud` and hides the on-prem-only tools, so the
140	// older `s4hana` / `ecc` values, an empty value and typos become `onprem`. ECC vs S/4HANA is
141	// SAP_VERSION / ABAP_RELEASE, not this key.
142	function normalizeSystemType(v) {
143	  const s = String(v || '').trim().toLowerCase();
144	  if (s === 'onprem' || s === 'cloud' || s === 'legacy') return s;
145	  return 'onprem';
146	}
147	
148	function loadKeyring() {
149	  try {
150	    return KEYRING_REQUIRE('@napi-rs/keyring').Entry;
151	  } catch {
152	    return null;
153	  }
154	}
155	class KeychainUnavailableError extends Error {
156	  constructor() {
157	    super('@napi-rs/keyring not available on this platform.');
158	    this.code = 'ERR_KEYCHAIN_UNAVAILABLE';
159	  }
160	}
161	function keychainWrite(service, account, password) {
162	  const Entry = loadKeyring();
163	  if (!Entry) throw new KeychainUnavailableError();
164	  new Entry(service, account).setPassword(password);
165	}
166	function keychainDelete(service, account) {
167	  const Entry = loadKeyring();
168	  if (!Entry) throw new KeychainUnavailableError();
169	  return new Entry(service, account).deletePassword();
170	}
171	
172	async function readStdinJson() {
173	  let buf = '';
174	  for await (const chunk of process.stdin) buf += chunk;
175	  if (!buf.trim()) return {};
176	  try {
177	    return JSON.parse(buf);
178	  } catch (e) {
179	    die(1, `Invalid JSON on stdin: ${e.message}`);
180	  }
181	}
182	
183	function listProfiles() {
184	  const dir = profilesDir();
185	  if (!existsSync(dir)) return [];
186	  return readdirSync(dir)
187	    .filter((f) => f !== '.trash' && statSync(join(dir, f)).isDirectory())
188	    .sort();
189	}
190	// Mask SAP_PASSWORD for display. Output must NEVER reveal a plaintext
191	// password. Accepted display values:
192	//   ""                                 — no password configured
193	//   "keychain:<service>/<account>"     — safe reference (no secret leaks)
194	//   "plaintext (masked)"               — a raw password sits in the env
195	//                                        file; surface the fact without
196	//                                        revealing the value so the user
197	//                                        knows to re-run `sap-option edit`.
198	function maskPasswordField(raw) {
199	  const v = String(raw || '');
200	  if (v === '') return '';
201	  if (v.startsWith('keychain:')) return v;
202	  return 'plaintext (masked)';
203	}
204	
205	function readProfile(alias) {
206	  const envPath = join(profilesDir(), alias, 'sap.env');
207	  if (!existsSync(envPath)) return null;
208	  const env = parseDotenv(readFileSync(envPath, 'utf8'));
209	  return {
210	    alias,
211	    tier: normalizeTier(env.SAP_TIER) || 'DEV',
212	    host: env.SAP_URL || '',
213	    client: env.SAP_CLIENT || '',
214	    username: env.SAP_USERNAME || '',
215	    language: env.SAP_LANGUAGE || '',
216	    systemType: env.SAP_SYSTEM_TYPE || '',
217	    version: env.SAP_VERSION || '',
218	    abapRelease: env.ABAP_RELEASE || '',
219	    industry: env.SAP_INDUSTRY || '',
220	    activeModules: env.SAP_ACTIVE_MODULES || '',
221	    description: env.SAP_DESCRIPTION || '',
222	    passwordRef: maskPasswordField(env.SAP_PASSWORD),
223	  };
224	}
225	function readActiveAlias(cwd) {
226	  const p = legacyFiles(cwd).pointer;
227	  if (!existsSync(p)) return null;
228	  const raw = readFileSync(p, 'utf8').trim();
229	  return raw.length > 0 ? raw : null;
230	}
231	
