531	    legacyEnv: legacyExists ? f.env : null,
532	    activePointer: pointerExists ? f.pointer : null,
533	    profilesDir: profilesExist ? profilesDir() : null,
534	    needsMigration,
535	    multiProfileSince: MULTI_PROFILE_SINCE,
