539	function validateProfile(p, otherProfiles) {
540	  const errors = [];
541	  const warnings = [];
542	
543	  if (!['DEV', 'QA', 'PRD'].includes(p.tier)) {
544	    errors.push(`invalid tier "${p.tier}" (expected DEV | QA | PRD)`);
545	  }
546	  if (!/^https?:\/\/[^ ]+[^/]$/.test(p.host || '')) {
547	    if (!p.host) errors.push('missing SAP_URL');
548	    else if (/\/$/.test(p.host)) errors.push(`SAP_URL must not end with /: ${p.host}`);
549	    else errors.push(`SAP_URL must start with http(s)://: ${p.host}`);
550	  }
551	  if (p.client && !/^\d{3}$/.test(p.client)) {
552	    errors.push(`SAP_CLIENT must be 3 digits: ${p.client}`);
553	  }
554	  if (!p.username) warnings.push('SAP_USERNAME is empty');
555	
556	  // Tier-vs-host sanity: PRD/QA profile with obvious dev/sbx/test host is suspicious.
557	  // Extract host from URL so we do not depend on scheme/port decoration.
558	  let hostOnly = (p.host || '').toLowerCase();
559	  try {
560	    hostOnly = new URL(p.host).hostname;
561	  } catch { /* leave as-is when URL is already invalid; upstream error will flag it */ }
562	  const hostRe = (words) => new RegExp(`(^|[.\\-])(${words})([.\\-]|$)`);
