async function cmdSetPassword(alias) {
  if (!alias) die(1, 'set-password: alias required');
  const envPath = join(profilesDir(), alias, 'sap.env');
  if (!existsSync(envPath)) die(3, `profile not found: ${alias}`);
  const env = parseDotenv(readFileSync(envPath, 'utf8'));
  const username = env.SAP_USERNAME || '';
  const password = askPassword(alias, username);
  const service = KEYCHAIN_SERVICE_DEFAULT;
  const account = `${alias}/${username}`;
  let passwordRef;
  try {
    keychainWrite(service, account, password);
    passwordRef = `keychain:${service}/${account}`;
  } catch (e) {
    process.stderr.write(
      `[set-password] WARNING: keychain unavailable (${e.message}); storing password as plaintext in profile env.\n`,
    );
    passwordRef = password;
  }
  writeFileSync(envPath, formatDotenv({ ...env, SAP_PASSWORD: passwordRef }));
  jsonOut({ ok: true, alias, passwordStored: passwordStoredKind(passwordRef) });
}

// L3 PreToolUse hook profile only — `MCP_BLOCKLIST_PROFILE` in sap.env (L4,
// MCP server guard) is a separate setting managed by sap-option and does not
// accept `custom`, so it is left untouched here.
async function cmdSetBlocklist(cwd, value, aliasArg) {
  const BLOCKLIST_VALID = ['strict', 'standard', 'minimal', 'custom'];
  const blocklistProfile = String(value || '').trim().toLowerCase();
  if (!BLOCKLIST_VALID.includes(blocklistProfile)) {
    die(1, `set-blocklist: value must be one of: ${BLOCKLIST_VALID.join(' | ')}`);
  }
  const alias = aliasArg || readActiveAlias(cwd);
  if (!alias) die(1, 'set-blocklist: no alias given and no active profile in cwd');
  const configPath = join(profilesDir(), alias, 'config.json');
  if (!existsSync(configPath)) die(3, `profile config not found: ${configPath}`);
  let config;
  try {
    config = JSON.parse(readFileSync(configPath, 'utf8'));
  } catch (e) {
    die(2, `set-blocklist: cannot parse ${configPath}: ${e.message}`);
  }
  const previous = config.blocklistProfile ?? null;
  config.blocklistProfile = blocklistProfile;
  writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);
  jsonOut({ ok: true, alias, blocklistProfile, previous, configPath });
}

async function cmdRemove(cwd, alias) {
  if (!alias) die(1, 'remove: alias required');
  const src = join(profilesDir(), alias);
  if (!existsSync(src)) die(3, `profile not found: ${alias}`);
  if (readActiveAlias(cwd) === alias) die(4, `cannot remove active profile: switch first`);
  const ts = new Date().toISOString().replace(/[:]/g, '-').replace(/\..*/, '');
  const dest = join(trashDir(), `${alias}-${ts}`);
  mkdirSync(trashDir(), { recursive: true });
  renameSync(src, dest);
  jsonOut({ ok: true, archivedTo: dest });
}

async function cmdPurge(all) {
  const dir = trashDir();
  if (!existsSync(dir)) {
    jsonOut({ ok: true, purged: [] });
    return;
  }
  const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
  const now = Date.now();
  const purged = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    const ageMs = now - statSync(p).mtimeMs;
    if (all || ageMs > sevenDaysMs) {
      rmSync(p, { recursive: true, force: true });
      purged.push(name);
    }
  }
  jsonOut({ ok: true, purged });
}

