// One-off: insert the offline-mode pointer line under the first "# " heading of each SKILL.md.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.argv[2];
const LINK = '[`common/offline-mode.md`](../../common/offline-mode.md)';
const blocked = 'blocked — reply with the stop line there and stop.';
const lines = {
  'project-dashboard': 'full — no SAP actuals; plan and edit mode as usual.',
  'role-matrix': 'full — new design only (no ST03N narrowing); `sync` is blocked.',
  'interface-mapping-spec': 'full — new interfaces from a field list or the consultant proposal; DDIC types marked unchecked.',
  'cbo-relation-map': 'full — only from an existing `graph.json`; collection is blocked.',
  setup: 'full — the connection question offers **Offline**; see `wizard-steps.md` § Offline path.',
  'sap-option': 'full — local configuration; `set-connection` switches the profile.',
  eco: 'the wrapped skill\'s class applies.',
  'ask-consultant': 'degraded — no system lookups; local knowledge order and the notice line from there.',
  'analyze-code': 'degraded — pasted / local-file source only; no where-used or semantic check.',
  'analyze-symptom': 'degraded — dump text / source pasted by the user; no dump feed, no transports.',
  'sap-doctor': 'degraded — plugin and profile layers only; connection layers `skipped (offline)`.',
};
for (const s of ['create-program', 'create-object', 'assist', 'program-to-spec', 'program-to-manual',
  'compare-programs', 'config-to-document', 'module-to-process', 'analyze-cbo-obj', 'smartform-preview',
  'smartform-from-pdf']) lines[s] = blocked;

for (const [skill, text] of Object.entries(lines)) {
  const p = join(root, 'skills', skill, 'SKILL.md');
  const src = readFileSync(p, 'utf8');
  if (src.includes('common/offline-mode.md')) { console.log(`skip ${skill} (already)`); continue; }
  const eol = src.includes('\r\n') ? '\r\n' : '\n';
  const rows = src.split(/\r?\n/);
  const end = rows.indexOf('---', 1); // end of frontmatter
  const h = rows.findIndex((r, i) => i > end && r.startsWith('# '));
  if (h < 0) throw new Error(`no heading in ${skill}`);
  rows.splice(h + 1, 0, '', `> **Offline profile** (${LINK}): ${text}`);
  writeFileSync(p, rows.join(eol));
  console.log(`ok ${skill} @${h + 2}`);
}

